preset.customCSS:
@import url("https://fonts.googleapis.com/css2?family=Song+Myung&family=Noto+Serif+KR:wght@400;600&display=swap");

/* 바깥 래퍼: 메시지 폭을 확보하고 가운데 정렬합니다. */
.risu-chat > div {
  padding: 1.1rem .75rem;
  margin: auto;
  display: flex;
  justify-content: center;
  align-items: center;
  width: 100%;
}
.risu-chat > div > div {
  width: 100%;
  margin: auto;
  display: flex;
  justify-content: center;
}

/* 글꼴과 크기: 본문 글자 크기는 --rtori-font-size로 바꿉니다. */
.rtori {
  --rtori-bg-fill: transparent;
  --rtori-blur: none;
  --rtori-bg-edge: none;
  --rtori-font-body: "Noto Serif KR", "Nanum Myeongjo", "Batang", serif;
  --rtori-font-display: "Song Myung", "Noto Serif KR", serif;
  --rtori-font-size: 16px;
  --rtori-line-height: 1.9;
  --rtori-para-gap: .9em;
  --rtori-dialog-weight: 700;
}

/* 본문: RisuAI 기본 색·글꼴 변수에 테마 값을 연결합니다. */
.rtori {
  --risu-font-family: var(--rtori-font-body);
  --FontColorStandard: var(--rtori-ink);
  --FontColorBold: var(--rtori-ink);
  --FontColorItalic: var(--rtori-muted);
  --FontColorItalicBold: var(--rtori-muted);
  --FontColorQuote1: var(--rtori-muted);
  --FontColorQuote2: var(--rtori-dialog);
  position: relative;
  isolation: isolate;
  width: 100%;
  min-width: 0;
  color: var(--rtori-ink);
  font-family: var(--rtori-font-body);
  font-size: var(--rtori-font-size);
  line-height: var(--rtori-line-height);
}
.rtori, .rtori *, .rtori *::before, .rtori *::after { box-sizing: border-box; }
/* 바깥 래퍼 보정(.risu-chat > div > div)이 테마 루트를 flex로 바꾸지 않게 루트 배치를 고정합니다. */
.rtori.rtori { display: block; }
.rtori__content {
  min-width: 0;
  color: var(--rtori-ink);
  word-break: keep-all;
  overflow-wrap: anywhere;
}
.rtori__content .chattext {
  --tw-prose-code: var(--rtori-ink);
  --tw-prose-pre-code: var(--rtori-ink);
  --tw-prose-pre-bg: var(--rtori-tint);
  max-width: none;
  color: var(--rtori-ink);
  font-size: var(--rtori-font-size) !important;
  line-height: var(--rtori-line-height) !important;
}
.rtori__content :is(p, li, td, th, blockquote) {
  font-size: var(--rtori-font-size);
  line-height: var(--rtori-line-height);
}
.rtori__content p { margin: 0 0 var(--rtori-para-gap); }
.rtori__content p:last-child { margin-bottom: 0; }
.rtori__content :is(h1, h2, h3, h4, h5, h6) {
  --risu-font-family: var(--rtori-font-display);
  margin: 1.3em 0 .55em;
  color: var(--rtori-ink);
  font-family: var(--rtori-font-display);
  line-height: 1.4;
  font-weight: 700;
}
.rtori__content h1 { font-size: calc(var(--rtori-font-size) * 1.6); }
.rtori__content h2 { font-size: calc(var(--rtori-font-size) * 1.35); }
.rtori__content h3 { font-size: calc(var(--rtori-font-size) * 1.15); }
.rtori__content :is(h4, h5, h6) { font-size: var(--rtori-font-size); }
.rtori__content strong { font-weight: 700; }
.rtori__content em { color: var(--rtori-muted); }
.rtori__content mark[risu-mark="quote1"],
.rtori__content mark[risu-mark="blockquote1"] { color: var(--rtori-muted); background: transparent; }
.rtori__content mark[risu-mark="quote2"],
.rtori__content mark[risu-mark="blockquote2"] {
  color: var(--rtori-dialog);
  font-weight: var(--rtori-dialog-weight);
  background: transparent;
}
.rtori__content blockquote {
  margin: 1em 0;
  padding: .3em 1em;
  border-left: 3px solid var(--rtori-line);
  color: var(--rtori-muted);
}
.rtori__content :is(ul, ol) { margin: 1em 0; padding-left: 1.5em; }
.rtori__content li { margin: .25em 0; color: var(--rtori-ink); }
.rtori__content li::marker { color: var(--rtori-muted); }
.rtori__content a { color: var(--rtori-accent); text-decoration: underline; }
.rtori__content hr { border: 0; border-top: 1px solid var(--rtori-line); margin: 1.5em 0; }
.rtori__content code {
  --risu-font-family: "IBM Plex Mono", ui-monospace, Consolas, monospace;
  padding: .1em .3em;
  border-radius: .2em;
  color: var(--rtori-ink);
  background: var(--rtori-tint);
  font-family: "IBM Plex Mono", ui-monospace, Consolas, monospace;
  font-size: calc(var(--rtori-font-size) * .88);
}
.rtori__content pre {
  max-width: 100%;
  overflow-x: auto;
  padding: .9em 1em;
  color: var(--rtori-ink);
  background: var(--rtori-tint);
  border-radius: .35rem;
  font-size: calc(var(--rtori-font-size) * .88);
  line-height: 1.5;
}
.rtori__content pre code { padding: 0; background: transparent; color: inherit; white-space: pre; overflow-wrap: normal; }
.rtori__content table {
  display: block;
  width: 100%;
  max-width: 100%;
  overflow-x: auto;
  border-collapse: collapse;
  margin: 1em 0;
}
.rtori__content :is(th, td) {
  padding: .5em .7em;
  color: var(--rtori-ink);
  border-bottom: 1px solid var(--rtori-line);
  text-align: left;
  vertical-align: top;
}
.rtori__content th { font-weight: 700; }
.rtori__content img { display: block; max-width: 100%; height: auto; margin: .75em auto; }
.rtori__content textarea.message-edit-area {
  width: 100%;
  max-width: 100%;
  min-width: 0;
  color: var(--rtori-ink) !important;
  background: var(--rtori-edit-bg) !important;
  border: 1px solid var(--rtori-line);
  border-radius: .4rem;
  font: inherit;
  font-size: var(--rtori-font-size) !important;
  line-height: var(--rtori-line-height) !important;
}

/* 조작부: 생성 정보와 버튼 */
.rtori__footer {
  --risu-theme-textcolor2: var(--rtori-muted);
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: .4rem .75rem;
  min-width: 0;
}
.rtori__info, .rtori__actions { min-width: 0; max-width: 100%; }
.rtori__info > div, .rtori__actions > div { flex-wrap: wrap; min-width: 0; gap: .3rem; }
.rtori__actions > div > div { flex-wrap: wrap; min-width: 0; }
.rtori__footer button {
  background: transparent;
  min-height: 1.9rem;
  padding: .25rem .4rem;
  border-radius: .3rem;
  white-space: normal;
}
.rtori__footer button:hover { background: var(--rtori-tint); }
.rtori :is(a, button, textarea):focus-visible { outline: 2px solid var(--rtori-accent); outline-offset: 2px; }

/* 아바타 틀: RisuAI가 넣는 배경 이미지 칸을 틀에 맞춥니다. */
.rtori__portrait { overflow: hidden; background: var(--rtori-tint); }
.rtori__portrait > * {
  width: 100% !important;
  height: 100% !important;
  min-width: 0 !important;
  min-height: 0 !important;
  background-size: cover !important;
  background-position: center 22% !important;
  border: 0 !important;
  border-radius: inherit !important;
}

.rtori__bg {
  position: absolute;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  border-radius: inherit;
  background: var(--rtori-bg-fill);
  -webkit-backdrop-filter: var(--rtori-blur);
  backdrop-filter: var(--rtori-blur);
  box-shadow: var(--rtori-bg-edge);
}

/* 구조: 동양풍 */

.rtori.rtori { display: grid; }
.rtori {
  grid-template-columns: auto minmax(0, 1fr);
  max-width: 52rem;
  margin: 0 auto;
  background:
    repeating-linear-gradient(115deg, var(--rtori-fiber) 0 1px, transparent 1px 9px),
    repeating-linear-gradient(25deg, var(--rtori-fiber) 0 1px, transparent 1px 13px),
    var(--rtori-paper);
  border-left: 1px solid var(--rtori-line);
  border-right: 1px solid var(--rtori-line);
  box-shadow: 0 4px 16px var(--rtori-shadow);
}
/* 족자의 위아래 가로대: 카드보다 조금 넓고, 굵기는 카드 폭에 맞춥니다 */
.rtori::before, .rtori::after {
  content: "";
  position: absolute;
  left: -.5rem;
  right: -.5rem;
  height: clamp(6px, 1.1vw, 11px);
  background: var(--rtori-rod);
  border-radius: 999px;
  box-shadow: 0 2px 4px var(--rtori-shadow);
  pointer-events: none;
}
.rtori::before { top: calc(clamp(6px, 1.1vw, 11px) / -2); }
.rtori::after { bottom: calc(clamp(6px, 1.1vw, 11px) / -2); }
/* 세로 띠 이름표 */
.rtori__band { display: flex; justify-content: center; padding: 1.3rem .45rem; background: var(--rtori-band); color: var(--rtori-band-ink); }
.rtori__name { writing-mode: vertical-rl; font-family: var(--rtori-font-display); font-size: 1.15em; letter-spacing: .3em; white-space: nowrap; }
.rtori--user .rtori__band { background: var(--rtori-band-user); }
.rtori__main { min-width: 0; padding: 1.3rem clamp(1rem, 4vw, 2rem) 1.1rem; }
/* 낙관 모양 초상 */
.rtori__portrait {
  float: right;
  width: var(--rtori-seal-w);
  aspect-ratio: 1;
  margin: 0 0 .7rem 1rem;
  padding: clamp(2px, .4vw, 4px);
  border: clamp(2px, .45vw, 4px) double var(--rtori-accent);
  border-radius: .3rem;
  background: var(--rtori-paper);
}
.rtori__portrait > * { border-radius: .15rem !important; }
.rtori { --rtori-seal-w: clamp(3.2rem, 10%, 5.2rem); }
.rtori--user { --rtori-seal-w: clamp(2.6rem, 7%, 3.6rem); }
.rtori__content::after { content: ""; display: block; clear: both; }
.rtori__footer { clear: both; margin-top: .8rem; padding-top: .5rem; border-top: 1px solid var(--rtori-line); font-size: .85em; }
@media (max-width: 520px) {
  .rtori { grid-template-columns: minmax(0, 1fr); }
  .rtori__band { justify-content: flex-start; padding: .45rem 1rem; }
  .rtori__name { writing-mode: horizontal-tb; letter-spacing: .15em; }
}

/* ── 배색과 소재: 이 블록만 바꾸면 같은 분류의 다른 변주가 됩니다. (먹) ── */
.rtori {
  --rtori-paper: #f2ede1;
  --rtori-fiber: rgba(120, 100, 70, .05);
  --rtori-rod: linear-gradient(#3a2e25, #1f1812);
  --rtori-band: #1d1b18;
  --rtori-band-user: #4f4a42;
  --rtori-band-ink: #f2ede1;
  --rtori-ink: #1d1b18;
  --rtori-muted: #6b645a;
  --rtori-accent: #9a342c;
  --rtori-dialog: #1d1b18;
  --rtori-shadow: rgba(40, 30, 20, .18);
  --rtori-line: #d9d0bf;
  --rtori-tint: #e8e1d2;
  --rtori-edit-bg: #faf7f0;
}
